"use strict";(self.webpackChunkdocusaurus_wiki=self.webpackChunkdocusaurus_wiki||[]).push([[9545],{9831:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>a,contentTitle:()=>u,default:()=>d,frontMatter:()=>l,metadata:()=>r,toc:()=>p});var s=n(7462),o=(n(7294),n(3905)),i=(n(6256),n(3767));const l={title:"Espionne"},u=void 0,r={unversionedId:"roles/espionne",id:"roles/espionne",title:"Espionne",description:"Description",source:"@site/docs/roles/espionne.mdx",sourceDirName:"roles",slug:"/roles/espionne",permalink:"/botc-wiki/docs/roles/espionne",draft:!1,tags:[],version:"current",frontMatter:{title:"Espionne"}},a={},p=[{value:"Description",id:"description",level:3},{value:"Exemples",id:"exemples",level:3},{value:"M\xe9caniques et conseils",id:"m\xe9caniques-et-conseils",level:3},{value:"Combattre l&#39;Espionne",id:"combattre-lespionne",level:3},{value:"Comment conter ?",id:"comment-conter-",level:3}],m={toc:p};function d(e){let{components:t,...n}=e;return(0,o.kt)("wrapper",(0,s.Z)({},m,n,{components:t,mdxType:"MDXLayout"}),(0,o.kt)(i.Z,{ESPIONNE:!0,header:!0,mdxType:"Role"}),(0,o.kt)("h3",{id:"description"},"Description"),(0,o.kt)("p",null,"Chaque nuit, regardez le Grimoire. Vous pouvez \xeatre consid\xe9r\xe9 comme Gentille et comme Villageoise ou Marginale, m\xeame si vous \xeates morte."),(0,o.kt)("p",null,"L\u2019Espionne peut appara\xeetre comme Gentille mais est en r\xe9alit\xe9 Mal\xe9fique. Elle voit aussi le Grimoire et donc elle conna\xeet le r\xf4le (et le statut) de tout le monde."),(0,o.kt)("ul",null,(0,o.kt)("li",{parentName:"ul"},(0,o.kt)("pre",{parentName:"li"},(0,o.kt)("code",{parentName:"pre"},"    Si un r\xf4le a une capacit\xe9 qui d\xe9tecte ou affecte un joueur Gentil, alors l\u2019Espionne pourrait \xeatre consid\xe9r\xe9e aupr\xe8s de lui comme un r\xf4le Gentil. Si un r\xf4le a une capacit\xe9 qui d\xe9tecte les Villageois et les Marginaux, alors l\u2019Espionne pourrait \xeatre consid\xe9r\xe9e comme une Villageoise sp\xe9cifique ou une Marginale sp\xe9cifique. Ceci est \xe0 la discr\xe9tion du Conteur, de voir comment l\u2019Espionne est consid\xe9r\xe9e. Elle peut \xeatre consid\xe9r\xe9e comme plusieurs r\xf4les ou alignements diff\xe9rents au cours de la m\xeame nuit.\n"))),(0,o.kt)("li",{parentName:"ul"},(0,o.kt)("pre",{parentName:"li"},(0,o.kt)("code",{parentName:"pre"},"    Un Espionne qui est consid\xe9r\xe9e comme une Villageoise ou Marginale n\u2019a pas la capacit\xe9 de ce Villageois ou de ce Marginal. Par exemple, un Espionne qui est consid\xe9r\xe9e comme un Mercenaire ne peut pas tuer le D\xe9mon en tirant sur lui.\n")))),(0,o.kt)("h3",{id:"exemples"},"Exemples"),(0,o.kt)("blockquote",null,(0,o.kt)("p",{parentName:"blockquote"},"La ",(0,o.kt)(i.Z,{LAVANDIERE:!0,mdxType:"Role"})," apprend qu\u2019il y a un ",(0,o.kt)(i.Z,{CORNEILLE:!0,mdxType:"Role"})," parmi David et Priscilla. David est le ",(0,o.kt)(i.Z,{MOINE:!0,mdxType:"Role"})," et Priscilla est l'Espionne, vu en tant que ",(0,o.kt)(i.Z,{CORNEILLE:!0,mdxType:"Role"}),".")),(0,o.kt)("blockquote",null,(0,o.kt)("p",{parentName:"blockquote"},"L'Espionne est situ\xe9 \xe0 c\xf4t\xe9 de l\u2019",(0,o.kt)(i.Z,{IMP:!0,mdxType:"Role"})," et de l\u2019",(0,o.kt)(i.Z,{EMPATHE:!0,mdxType:"Role"}),". Le ",(0,o.kt)(i.Z,{CUISTOT:!0,mdxType:"Role"})," obtient \u201c1\u201d parce que l'Espionne est consid\xe9r\xe9e comme Mal\xe9fique. Plus tard dans la nuit, l\u2019",(0,o.kt)(i.Z,{EMPATHE:!0,mdxType:"Role"})," obtient \u201c0\u201d car cette fois, l'Espionne est consid\xe9r\xe9e comme Gentille.")),(0,o.kt)("blockquote",null,(0,o.kt)("p",{parentName:"blockquote"},"L'Espionne nomine l' ",(0,o.kt)(i.Z,{IMMACULEE:!0,mdxType:"Role"})," et est ex\xe9cut\xe9e par la capacit\xe9 de l' ",(0,o.kt)(i.Z,{IMMACULEE:!0,mdxType:"Role"})," : le Conteur a d\xe9cid\xe9 que l'Espionne \xe9tait consid\xe9r\xe9e comme Villageois. La nuit qui suit, le ",(0,o.kt)(i.Z,{FOSSOYEUR:!0,mdxType:"Role"})," apprend que la ",(0,o.kt)(i.Z,{LAVANDIERE:!0,mdxType:"Role"})," est morte aujourd\u2019hui, parce que l'Espionne est maintenant consid\xe9r\xe9e comme la ",(0,o.kt)(i.Z,{LAVANDIERE:!0,mdxType:"Role"}),".")),(0,o.kt)("h3",{id:"m\xe9caniques-et-conseils"},"M\xe9caniques et conseils"),(0,o.kt)("ul",null,(0,o.kt)("li",{parentName:"ul"},"Si vous lisez ceci car vous \xeates maintenant l\u2019Espionne, ce conseil ne vous aidera pas mais si vous \xeates sur le point de joue votre premi\xe8re partie, demandez \xe0 votre Conteur de vous montrer \xe0 quoi ressemble le contenu d\u2019un Grimoire pour \xeatre pr\xe9par\xe9 quand il vous r\xe9veillera."),(0,o.kt)("li",{parentName:"ul"},"A condition que votre m\xe9moire soit bonne, vous commencez la partie en connaissant tout ! Vous voyez tous les joueurs et leurs r\xf4les. Utilisez ces informations pour que les Mal\xe9fiques prennent les bons bluffs et qu\u2019ils \xe9liminent des cibles prioritaires."),(0,o.kt)("li",{parentName:"ul"},"Il n\u2019est pas n\xe9cessaire de tout m\xe9moriser. Quelques \xe9l\xe9ments importants \xe0 retenir peuvent \xeatre les suivants :",(0,o.kt)("pre",{parentName:"li"},(0,o.kt)("code",{parentName:"pre"},"    - Un r\xf4le qui n\u2019est pas en jeu, que vous pourrez bluffer (peut-\xeatre plus d\u2019un au cas o\xf9 vous parleriez \xe0 un de vos comparse Sbire) et toutes les informations n\xe9cessaires pour consolider votre bluff.\n    - Quelques joueurs que votre <Role IMP />  devrait tuer ou votre <Role EMPOISONNEUR />  empoisonner comme le <Role MERCENAIRE />  ou le <Role FOSSOYEUR />.\n    - Tous les jetons de r\xf4les qui vous paraissent important.\n    - Prenez votre temps ! Le Conteur vous montrera le Grimoire aussi longtemps que n\xe9cessaire.\n"))),(0,o.kt)("li",{parentName:"ul"},"Dans le Grimoire, vous ne verrez pas seulement la composition du Village, mais aussi les jetons de rappel utilis\xe9s par le Conteur. Cela vous permettra de savoir qui est le ",(0,o.kt)(i.Z,{SOULARD:!0,mdxType:"Role"}),", qui a \xe9t\xe9 empoisonn\xe9, qui est le faux positif de la ",(0,o.kt)(i.Z,{VOYANTE:!0,mdxType:"Role"}),", qui le D\xe9mon a tu\xe9, sur qui la ",(0,o.kt)(i.Z,{LAVANDIERE:!0,mdxType:"Role"})," / l\u2019",(0,o.kt)(i.Z,{ARCHIVISTE:!0,mdxType:"Role"})," / l\u2019",(0,o.kt)(i.Z,{ENQUETEUR:!0,mdxType:"Role"})," ont eu des informations et l\u2019alignement des Voyageurs. Rappelez-vous que pouvez \xeatre consid\xe9r\xe9 comme Gentil pour une ",(0,o.kt)(i.Z,{LAVANDIERE:!0,mdxType:"Role"})," ou un ",(0,o.kt)(i.Z,{ARCHIVISTE:!0,mdxType:"Role"})," ; Si vous voyez cela dans le Grimoire, vous pouvez suivre ce bluff d\xe8s le d\xe9but."),(0,o.kt)("li",{parentName:"ul"},"En connaissant la composition du Village, il vous sera facile de choisir un bon bluff."),(0,o.kt)("li",{parentName:"ul"},"Vous avez aussi acc\xe8s imm\xe9diatement \xe0 des informations qui seraient difficiles \xe0 obtenir rapidement en temps normal, notamment les r\xf4les des diff\xe9rents joueurs. Cela vous permettra de bluffer efficacement des r\xf4les tels que la ",(0,o.kt)(i.Z,{LAVANDIERE:!0,mdxType:"Role"}),", le ",(0,o.kt)(i.Z,{FOSSOYEUR:!0,mdxType:"Role"})," ou le ",(0,o.kt)(i.Z,{CORNEILLE:!0,mdxType:"Role"})," puisque ce sont des r\xf4les qui obtiennent des informations sur les r\xf4les. Gagnez ainsi la confiance des autres joueurs, d\u2019autant plus s\u2019ils n\u2019ont pas r\xe9v\xe9l\xe9 leur r\xf4le publiquement ou s\u2019ils sont en train de bluffer un autre r\xf4le."),(0,o.kt)("li",{parentName:"ul"},"En bluffant l\u2019",(0,o.kt)(i.Z,{ARCHIVISTE:!0,mdxType:"Role"})," ou l'",(0,o.kt)(i.Z,{ENQUETEUR:!0,mdxType:"Role"})," et en choisissant de faire passer pour ",(0,o.kt)(i.Z,{SOULARD:!0,mdxType:"Role"})," ou Sbire des r\xf4les importants (",(0,o.kt)(i.Z,{EMPATHE:!0,mdxType:"Role"}),", ",(0,o.kt)(i.Z,{CORNEILLE:!0,mdxType:"Role"})," ou ",(0,o.kt)(i.Z,{MAIRE:!0,mdxType:"Role"}),"), vous pourrez semer le doute sur les informations r\xe9colt\xe9es par le Village.  "),(0,o.kt)("li",{parentName:"ul"},"Vous pouvez fournir des informations de premi\xe8re importance \xe0 votre D\xe9mon et aux autres Sbires (tel que l\u2019",(0,o.kt)(i.Z,{EMPOISONNEUR:!0,mdxType:"Role"}),"). Cela vous permet de cibler des r\xf4les puissants en d\xe9but de partie et de les neutraliser avant qu\u2019ils ne posent trop de probl\xe8mes \xe0 votre \xe9quipe. En g\xe9n\xe9ral, vous allez avoir besoin de nombreuses conversations priv\xe9es avec vos acolytes pour transmettre vos informations, pr\xe9parez vous un alibi solide pour expliquer toutes ces messes basses !"),(0,o.kt)("li",{parentName:"ul"},"Vous apparaitrez la plupart du temps comme joueur Gentil face aux r\xf4les comme l\u2019",(0,o.kt)(i.Z,{EMPATHE:!0,mdxType:"Role"}),", le ",(0,o.kt)(i.Z,{CUISTOT:!0,mdxType:"Role"})," ou le ",(0,o.kt)(i.Z,{FOSSOYEUR:!0,mdxType:"Role"}),". Gr\xe2ce \xe0 cela, vous pourrez facilement gagner leur confiance. Cela fait aussi de vous un bon candidat pour devenir le ",(0,o.kt)(i.Z,{IMP:!0,mdxType:"Role"}),". Demandez-lui de starpass (le ",(0,o.kt)(i.Z,{IMP:!0,mdxType:"Role"})," se suicide pour redonner son r\xf4le \xe0 un de ses Sbires) lorsque vous serez compl\xe8tement innocent\xe9 aux yeux du Village."),(0,o.kt)("li",{parentName:"ul"},"Vous \xeates le seul Mal\xe9fique capable d\u2019activer la capacit\xe9 de l' ",(0,o.kt)(i.Z,{IMMACULEE:!0,mdxType:"Role"}),". Les personnes qui meurent de cette mani\xe8re sont habituellement celles qui obtiennent le plus de cr\xe9dit aux yeux du village. En donnant de mauvaises informations et en vous sacrifiant sur l' ",(0,o.kt)(i.Z,{IMMACULEE:!0,mdxType:"Role"}),", cela vous permettra d\u2019\xeatre au c\u0153ur de l\u2019enqu\xeate et d\u2019orienter l\u2019enqu\xeate dans le mauvais sens. De la m\xeame mani\xe8re, si vous savez qu\u2019il y a un ",(0,o.kt)(i.Z,{FOSSOYEUR:!0,mdxType:"Role"})," en jeu, laissez-vous ex\xe9cuter, vous devriez \xeatre reconnu comme Gentil et cela les incitera \xe0 croire vos informations. La contrepartie \xe9tant qu\u2019il ne vous restera qu\u2019un dernier vote. "),(0,o.kt)("li",{parentName:"ul"},"L'Espionne est tr\xe8s efficace pour mettre en place des bluffs \xe0 plusieurs. Par exemple, vous vous d\xe9voilez en tant que ",(0,o.kt)(i.Z,{LAVANDIERE:!0,mdxType:"Role"}),", ",(0,o.kt)(i.Z,{ARCHIVISTE:!0,mdxType:"Role"})," ou ",(0,o.kt)(i.Z,{CORNEILLE:!0,mdxType:"Role"})," et vous confirmez le bluff de votre D\xe9mon (pensez tout de m\xeame \xe0 l\u2019en informer)."),(0,o.kt)("li",{parentName:"ul"},"Vous serez souvent d\xe9tect\xe9 comme Gentil, ce qui est g\xe9nial si vous \xeates assis \xe0 c\xf4t\xe9 d'un ",(0,o.kt)(i.Z,{EMPATHE:!0,mdxType:"Role"})," ou si un ",(0,o.kt)(i.Z,{CUISTOT:!0,mdxType:"Role"})," est en jeu. Cela servira votre objectif de vous infiltrer parmi les Gentils et gagner leur confiance. "),(0,o.kt)("li",{parentName:"ul"},"Vous pouvez aussi passer des informations \xe0 vos acolytes de mani\xe8re publique, si vous arrivez \xe0 le faire subtilement. Par exemple : \u201cJ\u2019ai entendu dire qu\u2019il y avait un ",(0,o.kt)(i.Z,{MERCENAIRE:!0,mdxType:"Role"})," dans la partie mais je ne dirai \xe9videmment pas de qui il s\u2019agit pour le prot\xe9ger\u201d. Ainsi, John devrait comprendre ce que vous faites, et commencera \xe0 bluffer le ",(0,o.kt)(i.Z,{MERCENAIRE:!0,mdxType:"Role"}),"."),(0,o.kt)("li",{parentName:"ul"},"Assurez-vous en tant que Mal\xe9fique que le Conteur sache quel r\xf4le vous bluffez, cela lui permettra de confirmer votre bluff aux autres joueurs. Par exemple, si vous \xeates en train de bluffer ",(0,o.kt)(i.Z,{MAJORDOME:!0,mdxType:"Role"})," et que vous \xeates ex\xe9cut\xe9, le Conteur montrera au ",(0,o.kt)(i.Z,{FOSSOYEUR:!0,mdxType:"Role"})," le jeton du ",(0,o.kt)(i.Z,{MAJORDOME:!0,mdxType:"Role"}),"."),(0,o.kt)("li",{parentName:"ul"},"Vous n\u2019\xeates pas oblig\xe9 de m\xe9moriser tout le Grimoire la premi\xe8re nuit. Puisque vous le voyez toutes les nuits, m\xe9morisez quelques r\xf4les \xe0 chaque fois.")),(0,o.kt)("h3",{id:"combattre-lespionne"},"Combattre l'Espionne"),(0,o.kt)("ul",null,(0,o.kt)("li",{parentName:"ul"},"Il faut commencer par le d\xe9tecter pour mieux le combattre. Si le D\xe9mon tue des r\xf4les importants rapidement, si la ",(0,o.kt)(i.Z,{VOYANTE:!0,mdxType:"Role"})," et le ",(0,o.kt)(i.Z,{FOSSOYEUR:!0,mdxType:"Role"})," meurent dans les premiers et que le ",(0,o.kt)(i.Z,{CORNEILLE:!0,mdxType:"Role"})," et le ",(0,o.kt)(i.Z,{SOLDAT:!0,mdxType:"Role"})," ne sont jamais attaqu\xe9s, il se pourrait bien qu\u2019un Espionne soit en jeu."),(0,o.kt)("li",{parentName:"ul"},"Si vous pensez qu\u2019il y a un Espionne en jeu, partez du principe que les Mal\xe9fiques ont acc\xe8s \xe0 tous les r\xf4les et interactions et qu\u2019il est dans l\u2019int\xe9r\xeat des Gentils de partager publiquement toutes les informations. Cela vous permettra de vous coordonner plus facilement, mais aussi de d\xe9busquer des Mal\xe9fiques qui n\u2019\xe9taient pas encore compl\xe8tement install\xe9s dans leur bluffs."),(0,o.kt)("li",{parentName:"ul"},"Faites attention aux interactions entre joueurs, particuli\xe8rement celles qui vous paraissent longues (surtout le premier jour) ou r\xe9p\xe9titives. Une Espionne et un D\xe9mon ont plus \xe0 \xe9changer que des joueurs lambda."),(0,o.kt)("li",{parentName:"ul"},"Si vous \xeates l' ",(0,o.kt)(i.Z,{IMMACULEE:!0,mdxType:"Role"}),", le ",(0,o.kt)(i.Z,{FOSSOYEUR:!0,mdxType:"Role"})," ou le ",(0,o.kt)(i.Z,{CORNEILLE:!0,mdxType:"Role"}),", restez \xe0 l\u2019aff\xfbt des joueurs qui veulent mourir pour qu\u2019on confirme leur identit\xe9. Puisque l'Espionne peut \xeatre vue comme \xe9tant bon, il peut avoir envie de s\u2019innocenter de cette mani\xe8re afin de cr\xe9dibiliser les informations qu\u2019il transmettra par la suite."),(0,o.kt)("li",{parentName:"ul"},"En tant qu'Espionne, il est tr\xe8s facile de bluffer des r\xf4les comme la ",(0,o.kt)(i.Z,{LAVANDIERE:!0,mdxType:"Role"})," ou le ",(0,o.kt)(i.Z,{CORNEILLE:!0,mdxType:"Role"}),". Ces r\xf4les ont besoin de conna\xeetre l\u2019identit\xe9 d\u2019autres joueurs et sont donc habituellements plus compliqu\xe9s \xe0 bluffer pour les Mal\xe9fiques. Si vous suspectez la pr\xe9sence d\u2019un Espionne, gardez un \u0153il sur les joueurs qui pr\xe9tendent \xeatre ces r\xf4les."),(0,o.kt)("li",{parentName:"ul"},"Les r\xf4les de d\xe9tection comme l\u2019",(0,o.kt)(i.Z,{EMPATHE:!0,mdxType:"Role"})," ou le ",(0,o.kt)(i.Z,{CUISTOT:!0,mdxType:"Role"})," peuvent avoir des informations qui ne semblent pas \xeatre coh\xe9rentes ou changeantes. Si c\u2019est le cas, c\u2019est peut-\xeatre d\xfb \xe0 la capacit\xe9 de l'Espionne, qui est identifi\xe9e parfois en tant que Gentille et parfois en tant que Mal\xe9fique."),(0,o.kt)("li",{parentName:"ul"},"L\u2019Espionne saura s\u2019il est vu par la ",(0,o.kt)(i.Z,{LAVANDIERE:!0,mdxType:"Role"}),"  ou l\u2019",(0,o.kt)(i.Z,{ARCHIVISTE:!0,mdxType:"Role"}),"  comme joueur Gentil mais il ne saura pas quel r\xf4le. Si un de ces deux pr\xe9tend avoir vu un r\xf4le qu\u2019aucune des deux personnes ne pr\xe9tend \xeatre, peut \xeatre qu\u2019un Espionne a \xe9t\xe9 consid\xe9r\xe9 comme Gentil pour eux. Cela peut \xeatre particuli\xe8rement impactant si l\u2019",(0,o.kt)(i.Z,{ARCHIVISTE:!0,mdxType:"Role"})," a vu un Marginal et qu\u2019un des joueurs qu\u2019il a vu pr\xe9tend \xeatre un autre Marginal. Peut-\xeatre que l\u2019Espionne a saisi une chance sur les quatre et s\u2019est tromp\xe9."),(0,o.kt)("li",{parentName:"ul"},"Si le r\xf4le d'Espionne est r\xe9v\xe9l\xe9 \xe0 un ",(0,o.kt)(i.Z,{FOSSOYEUR:!0,mdxType:"Role"})," ou \xe0 un ",(0,o.kt)(i.Z,{CORNEILLE:!0,mdxType:"Role"}),", il est assez probable que ce soit une fausse information donn\xe9e par le Conteur : les joueurs doivent essayer de comprendre quelle m\xe9canique est \xe0 l\u2019origine de cette information suspecte."),(0,o.kt)("li",{parentName:"ul"},"L\u2019",(0,o.kt)(i.Z,{IMP:!0,mdxType:"Role"})," aura tendance \xe0 se tuer lui-m\xeame pour que l'Espionne devienne le nouveau D\xe9mon (=starpass), surtout si celui-ci s\u2019est compl\xe8tement innocent\xe9 aux yeux du village. Faites attention aux morts de nuit qui, \xe0 priori, n\u2019ont pas de sens ; cela vous permettra de d\xe9tecter ce genre de man\u0153uvre.")),(0,o.kt)("h3",{id:"comment-conter-"},"Comment conter ?"),(0,o.kt)("p",null,"Chaque nuit, r\xe9veillez l\u2019Espionne et montrez-lui le Grimoire tant qu\u2019il en a besoin. Rendormez l\u2019Espionne."),(0,o.kt)("p",null,"A chaque fois que l\u2019Espionne est vis\xe9e par une capacit\xe9 qui d\xe9tecte ou affecte les Gentils, choisissez pour quel r\xf4le et quel alignement est consid\xe9r\xe9 l\u2019Espionne. (Faites ce qui est appropri\xe9, tel que montrer un jeton de r\xf4le gentil, faire oui de la t\xeate, donner des chiffres avec vos doigts ou faire fonctionner une capacit\xe9 qui n\u2019affecte normalement que les Gentils, Villageois ou Marginal.)"),(0,o.kt)("p",null,"Rappelez-vous de garder votre Grimoire rang\xe9 et \xe0 jour et de le montrer \xe0 l\u2019Espionne avec la bonne orientation pour que l\u2019Espionne reconnaisse facilement qui est qui."))}d.isMDXComponent=!0}}]);